WITH new_admins (user_id, username, added_by, added_at) AS (VALUES (8133121673, 'velassya', 7221553045,
                                                                    '2025-07-11 17:52:54.282767'::timestamp),
                                                                   (7221553045, 'aam_cheshire', 7221553045,
                                                                    '2025-07-11 17:52:54.282767'::timestamp),
                                                                   (728299747, 'PhOeNiX529', 7221553045,
                                                                    '2025-07-16 15:46:03.465830'::timestamp),
                                                                   (1692092323, 'Eliss_son', 7221553045,
                                                                    '2025-07-19 13:01:28.136924'::timestamp)),
     ins_users AS (
         INSERT INTO public.users (user_id, username)
             SELECT na.user_id, na.username
             FROM new_admins na
                      LEFT JOIN public.users u ON u.user_id = na.user_id
             WHERE u.user_id IS NULL
             RETURNING user_id)
INSERT
INTO public.admins (user_id, username, added_by, added_at)
SELECT user_id, username, added_by, added_at
FROM new_admins
ON CONFLICT (user_id) DO UPDATE
    SET username = EXCLUDED.username,
        added_by = EXCLUDED.added_by,
        added_at = EXCLUDED.added_at;

