                  'AgACAgQAAxkBAAJQ6WhxRGJ_xXRNcXkkbu9msn_TBRHNAALyxzEbWVmJU1EKu-uhqCJSAQADAgADeQADNgQ', 300,
                  '2025-09-18 19:30:00.000000', '2025-09-18 20:01:00.000000', 'scheduled', '2025-09-12 18:41:59.945354',
                  'алмазы', '', null, false, false, false,
                  'AgACAgIAAxkBAAECB7BoxD9HbgIOKwlT-_4eaevCOqQDbwACqfUxG1Y7KUpaH4VKiSZ54AEAAwIAA3kAAzYE', null, false),
                 (1776, 'Мелодия скорости', 'Лиа',
                  'AgACAgQAAxkBAAJPJ2hxP60kRn-xRjs9fFnoSj6QV2IGAALBxzEbWVmJU9a_-JXFwtfdAQADAgADeQADNgQ', 400,
                  '2025-09-18 20:00:00.000000', '2025-09-18 20:31:00.000000', 'scheduled', '2025-09-12 20:06:08.322792',
                  'алмазы', '', null, false, false, false,
                  'AgACAgIAAxkBAAECCEtoxFMAAWPHQJa66uPQI00RRbdnARQAAqz6MRv7NCBKYu_CMUO9LigBAAMCAAN5AAM2BA', null,
                  false)),
     v AS (SELECT auction_id,
                  card_name,
                  hero_name,
                  image_id,
                  start_price,
                  start_time_s::timestamp AS start_time,
                  end_time_s::timestamp   AS end_time,
                  status,
                  created_at_s::timestamp AS created_at,
                  CASE lower(btrim(currency))
                      WHEN 'алмазы' THEN 'алмазы'
                      WHEN 'кристаллы' THEN 'алмазы'
                      WHEN 'кристалл' THEN 'алмазы'
                      WHEN 'чашка' THEN 'чашки'
                      WHEN 'чашки' THEN 'чашки'
                      ELSE NULL -- такие строки не вставляем (пройдет chk_auctions_currency)
                      END                 AS currency,
                  comment,
                  message_id,
                  notified_start,
                  notified_1min,
                  notified_end,
                  proof_photo_id,
                  discussion_message_id,
                  notified_card_subs
           FROM raw),
/* дедуп по discussion_message_id (NOT NULL) */
     dedup_disc AS (SELECT *
                    FROM v
                    WHERE discussion_message_id IS NULL
                    UNION ALL
                    SELECT DISTINCT ON (discussion_message_id) *
                    FROM v
                    WHERE discussion_message_id IS NOT NULL
                    ORDER BY discussion_message_id, auction_id),
/* дедуп по message_id (NOT NULL) */
     dedup AS (SELECT *
               FROM dedup_disc
               WHERE message_id IS NULL
               UNION ALL
               SELECT DISTINCT ON (message_id) *
               FROM dedup_disc
               WHERE message_id IS NOT NULL
               ORDER BY message_id, auction_id),
/* отсечь уже существующие записи в БД по обоим уникальным индексам */
     to_insert AS (SELECT d.*
                   FROM dedup d
                            LEFT JOIN public.auctions a1
                                      ON d.discussion_message_id IS NOT NULL
                                          AND a1.discussion_message_id = d.discussion_message_id
                            LEFT JOIN public.auctions a2
                                      ON d.message_id IS NOT NULL
                                          AND a2.message_id = d.message_id
                   WHERE d.currency IS NOT NULL
                     AND a1.auction_id IS NULL
                     AND a2.auction_id IS NULL)
INSERT
INTO public.auctions
(auction_id, card_name, hero_name, image_id, start_price,
 start_time, end_time, status, created_at, currency, comment, message_id,
 notified_start, notified_1min, notified_end, proof_photo_id,
 discussion_message_id, notified_card_subs)
SELECT *
FROM to_insert
ON CONFLICT DO NOTHING;

