     dedup AS (SELECT *
               FROM (SELECT r.*,
                            ROW_NUMBER() OVER (
                                PARTITION BY user_id, card_id
                                ORDER BY (created_at_s)::timestamp
                                ) AS rn
                     FROM raw r) t
               WHERE rn = 1),
     to_insert AS (SELECT d.*
                   FROM dedup d
                            LEFT JOIN public.user_subscriptions u
                                      ON u.user_id = d.user_id AND u.card_id = d.card_id
                   WHERE u.user_id IS NULL)
INSERT
INTO public.user_subscriptions
    (user_id, card_id, created_at)
SELECT user_id, card_id, card_name, hero_name, (created_at_s)::timestamp
FROM to_insert
-- если сделали индекс выше, можно упростить:
-- ON CONFLICT (user_id, card_id) DO NOTHING
;


